import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;

    static long modExponentiation(long base, long exponent, long modulus) {
        long result = 1;
        for (long i = 0; i < exponent; i++) {
            result = (result * base) % modulus;
        }
        return result;
    }

    static long compute_power(long base, long exponent) {
        long res = 1;
        for (long i = 0; i < exponent; i++) {
            res = (res * base) % MOD_CONST;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k % p == 1) {
            System.out.println(compute_power(p, p));
            sc.close();
            return;
        }
        if (k % p == 0) {
            System.out.println(compute_power(p, p - 1));
            sc.close();
            return;
        }
        long a = 1;
        while (true) {
            if ((p - 1) % a != 0) {
                a++;
                continue;
            }
            if (modExponentiation(k, a, p) == 1) {
                break;
            } else {
                a++;
            }
        }
        System.out.println(compute_power(p, (p - 1) / a));
        sc.close();
    }
}
